import SwiftUI
import MapKit
struct DogWalkMap: View {
    @State private var camera: MapCameraPosition = .automatic
    private let center = CLLocationCoordinate2D(
        latitude: 55.75, longitude: 37.61
    )
    var body: some View {
        VStack {
            Map(position: $camera) {
                Marker("Площадка", coordinate: center)
            }
            Button("Показать площадку") {
                let span = MKCoordinateSpan(
                    latitudeDelta: 0.01, longitudeDelta: 0.01
                )
                camera = .region(.init(center: center, span: span))
            }
        }
    }
}

Кнопка меняет видимый регион, а не выбор точки. Проверено компиляцией; анимация и нажатие требуют UI-проверки.

