import Foundation
struct BusStop { let id: Int; let title: String }
func uniqueStops(_ rows: [BusStop]) -> [BusStop] {
    var seen = Set<Int>()
    var result: [BusStop] = []
    for row in rows where seen.insert(row.id).inserted {
        result.append(row)
    }
    return result
}
let rows = [BusStop(id: 7, title: "Северная"),
    BusStop(id: 7, title: "Копия"), BusStop(id: 8, title: "Северная")]
print(uniqueStops(rows).map { $0.id })

Вывод [7, 8]. Чистим дубли идентичности до построения меток, а не заменяем id названием.

