struct RecyclingMap: View {
    private let coordinate = CLLocationCoordinate2D(
        latitude: 55.75, longitude: 37.61
    )
    var body: some View {
        Map {
            Annotation("Приём стекла", coordinate: coordinate) {
                Image(systemName: "arrow.3.trianglepath")
                    .accessibilityLabel("Пункт приёма стекла")
            }
        }
    }
}

Annotation размещает собственный вид на координате; accessibilityLabel объясняет символ. Взаимодействие VoiceOver не проверено.
